function countTopicMessages(topic, broker) {
  let raw;
  try {
    raw = execFileSync(
      "rpk",
      ["topic", "describe", topic, "-p", "--format", "json", "--brokers", broker],
      { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
  } catch (error) {
    if (error && typeof error === "object" && "code" in error && error.code === "ENOENT") {
      throw new Error("Missing dependency: `rpk` is required to inspect Redpanda topic offsets");
    }
    const stderr =
      error && typeof error === "object" && "stderr" in error && typeof error.stderr === "string"
        ? error.stderr.trim()
        : "";
    throw new Error(stderr || `Unable to describe Redpanda topic ${topic}`);
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error("Unable to parse `rpk topic describe` output");
  }

  const topicInfo = Array.isArray(parsed) ? parsed[0] : null;
  if (!topicInfo) {
    throw new Error(`Missing configuration: Redpanda topic ${topic} was not found`);
  }
  if (!Array.isArray(topicInfo.partitions)) {
    throw new Error(`Topic metadata for ${topic} is missing partition details`);
  }

  return topicInfo.partitions.reduce((sum, partition) => {
    const start = Number(partition.log_start_offset ?? 0);
    const end = Number(partition.high_watermark ?? 0);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) {
      throw new Error(`Invalid offsets returned for topic ${topic}`);
    }
    return sum + (end - start);
  }, 0);
}

